INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7523442, 1202055, 68504, '<td valign="top">I like the gloom from which the peppers emerge. I disagree with Bear''s critique: if you did what he says to do, I think it would lose that sense of emergence.</td>', 'I like the gloom from which the peppers emerge. I disagree with Bear''s critique: if you did what he says to do, I think it would lose that sense of emergence.', '2017-07-14 13:25:23.000000', NULL, 0),
(7523443, 1201651, 68504, '<td valign="top">that is one fine painting.</td>', 'that is one fine painting.', '2017-07-14 13:27:12.000000', NULL, 0),
(7523449, 1202203, 163081, '<td valign="top">How did you manage to write Chinese? I tried to use Chinese before, but it I got similar codes as in Tibi''s comment.<br/> <br/></td>', 'How did you manage to write Chinese? I tried to use Chinese before, but it I got similar codes as in Tibi''s comment. ', '2017-07-14 14:12:59.000000', NULL, 0),
(7523454, 1202055, 141319, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Bear_Music:</b></div><hr/><i> Whoa! Here I am scrolling along voting bright, bright, BRIGHT red pictures, then WHOMP! It''s the Cave where Red was born! In a lot of ways I like this a lot, but for me it''s not as well-realized as it could have been. A little careful work in post in the darkest part of the peppers to bring them up half a zone or so would have provided a boost to the 3-dimensionality of the image. The empty space to the right isn''t helping you at all, all the more so because the pepper/BG division is so danged vertical. It''s such and abrupt stoppage. I''d love to see one more pepper low and in the back on the right, fading into the cave :-) Also it would be great if you could change the WB on the bottom-most reflection so it was a lot less blue... A 7 from me. </i></td></tr></table> <br/> <br/>Thank you so much for this long and detailed comment :-), really appreciate it. I had not thought about another pepper in the BG, I tried a few different placements of the peppers, but liked this the best (of what I took). I HAD thought and even done a few versions where the peppers in the front especially are just a notch brighter, and I like them much better, but this was "minimal" editing .... I may be totally wrong, but I thought non of that was allowed in Minimal? <br/> <br/>From the rules: <br/>You may not...<br/> <br/>    make any other adjustments to your image than those listed above. This includes, but is not limited to, cropping, adjusting brightness, hue/saturation, levels, curves, etc. Except as provided above, your image as entered must be identical to the original image as it came</td>', 'Originally posted by Bear_Music: Whoa! Here I am scrolling along voting bright, bright, BRIGHT red pictures, then WHOMP! It''s the Cave where Red was born! In a lot of ways I like this a lot, but for me it''s not as well-realized as it could have been. A little careful work in post in the darkest part of the peppers to bring them up half a zone or so would have provided a boost to the 3-dimensionality of the image. The empty space to the right isn''t helping you at all, all the more so because the pepper/BG division is so danged vertical. It''s such and abrupt stoppage. I''d love to see one more pepper low and in the back on the right, fading into the cave :-) Also it would be great if you could change the WB on the bottom-most reflection so it was a lot less blue... A 7 from me.   Thank you so much for this long and detailed comment :-), really appreciate it. I had not thought about another pepper in the BG, I tried a few different placements of the peppers, but liked this the best (of what I took). I HAD thought and even done a few versions where the peppers in the front especially are just a notch brighter, and I like them much better, but this was "minimal" editing .... I may be totally wrong, but I thought non of that was allowed in Minimal?  From the rules: You may not...     make any other adjustments to your image than those listed above. This includes, but is not limited to, cropping, adjusting brightness, hue/saturation, levels, curves, etc. Except as provided above, your image as entered must be identical to the original image as it came', '2017-07-14 14:58:08.000000', NULL, 0),
(7523465, 1202145, 59029, '<td valign="top">Greetings from the Critique Club!<br/> <br/>Hi Marcel, this was a lucky little surprise to find amongst all those flowers you had to choose from :-)  I too see and love the tongue-like aspect of the petal, and the tininess of the slug - this did very well considering that it''s a slug and not something cute like a butterfly.  The shallow dof works very well and all your settings look fine to me.  Two small changes I might suggest is perhaps stopping up to f3.2 or f.4, as usually lenses aren''t at their sharpest wide open, and as this was a Minimal challenge (and cropping ain''t allowed) just doing more to fill the frame with the petal. The left half, though it does help draw the eye to the petal and slug, is a black void just sitting there twiddling its thumbs so it may as well be put to good use!<br/> <br/>Overall a very good and charming image, and belated congrats on the top ten!  Keep up the good work and I look forward to seeing more from you in the future :-)<br/> <br/>Susan</td>', 'Greetings from the Critique Club! Hi Marcel, this was a lucky little surprise to find amongst all those flowers you had to choose from :-)  I too see and love the tongue-like aspect of the petal, and the tininess of the slug - this did very well considering that it''s a slug and not something cute like a butterfly.  The shallow dof works very well and all your settings look fine to me.  Two small changes I might suggest is perhaps stopping up to f3.2 or f.4, as usually lenses aren''t at their sharpest wide open, and as this was a Minimal challenge (and cropping ain''t allowed) just doing more to fill the frame with the petal. The left half, though it does help draw the eye to the petal and slug, is a black void just sitting there twiddling its thumbs so it may as well be put to good use! Overall a very good and charming image, and belated congrats on the top ten!  Keep up the good work and I look forward to seeing more from you in the future :-) Susan', '2017-07-14 16:47:43.000000', NULL, 0),
(7523477, 1202257, 104230, '<td valign="top">Hi Viv,<br/> <br/>I''ll comment on the moth that''s attracted to the flowers.  Good catch! <br/> <br/>I was "introduced" to this interesting creature when one visited our Buddliea blooms last year.  They have a really unusual movement. I had no idea what I was seeing at first. <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1185389" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/2000-2999/2327/120/Copyrighted_Image_Reuse_Prohibited_1185389.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/2000-2999/2327/120/Copyrighted_Image_Reuse_Prohibited_1185389.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/2000-2999/2327/120/Copyrighted_Image_Reuse_Prohibited_1185389.jpg"/></a> <br/> <br/> <br/> <br/></td>', 'Hi Viv, I''ll comment on the moth that''s attracted to the flowers.  Good catch!  I was "introduced" to this interesting creature when one visited our Buddliea blooms last year.  They have a really unusual movement. I had no idea what I was seeing at first.      ', '2017-07-14 20:20:21.000000', NULL, 0),
